def aid(x,ns):return {'$type':'ArtifactIdentity','kind':{'$enum':'IdentityKind','value':'CONTENT_IDENTITY'},'namespace':ns,'sha256':hashlib.sha256(cb(x)).hexdigest()}
def write(n,x):(E/n).write_text(json.dumps(x,sort_keys=True,indent=2,ensure_ascii=False)+'\n')
